// WebRA's own pixel art (art/pixel-data.js, generated by tools/gen_pixel_art.py):
// 8-bit frames in Red Alert's style for actors Red Alert has no art for
// (OpenRA drew theirs itself, data/source/bits.txt). The frames use Red
// Alert's index conventions (content/palette.js: 0 transparent, 4 shadow, 80
// to 95 the owner's colour) on WebRA's own palette, so they go through the
// same path as the original graphics: a pose table per body slot (idle and
// damaged frames, js/sprites.js buildAtlas `slots`), with or without the
// original graphics installed (installed art and texture packs come first).
//
// Images are stored at two atlas pixels per world pixel, like WebRA's vector
// art (sprites.js RES), so they stay crisp with the linear sampler of WebRA's
// atlas as well as the nearest one of the original graphics.

import { PIXEL_ART, PIXEL_PALETTE } from './pixel-data.js';
import { rect } from './kit.js';
import { indexedImage, stillPoses } from '../content/atlas.js';
import { ACTOR_SHADOW, SHADOW_ALPHA, paletteLookup } from '../content/palette.js';

/** Atlas pixels per world pixel of the stored images. */
export const PIXEL_RES = 2;

const decode = (b64) => Uint8Array.from(atob(b64), (ch) => ch.charCodeAt(0));

let lookupCache = null;
/** The colour and team mask lookup of WebRA's palette (content/palette.js paletteLookup). */
export function pixelLookup() {
  lookupCache ??= paletteLookup(decode(PIXEL_PALETTE), { remap: true, shadow: ACTOR_SHADOW });
  return lookupCache;
}

/** The pixel art of an actor id (art/pixel-data.js PIXEL_ART), or null. */
export function pixelArtOf(id) {
  return PIXEL_ART[String(id).toUpperCase()] ?? null;
}

/** Frame `k` of `art` as an 8-bit frame ({ width, height, data }). */
export function pixelFrame(art, k) {
  return { width: art.width, height: art.height, data: decode(art.frames[k]) };
}

/** An atlas image scaled up `n` times (nearest), drawn `1 / n` the size: the same world size. */
function upscaled(img, n) {
  const w = img.width * n;
  const h = img.height * n;
  const color = new Uint8ClampedArray(w * h * 4);
  const mask = img.mask ? new Uint8Array(w * h) : null;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const s = Math.floor(y / n) * img.width + Math.floor(x / n);
      color.set(img.color.subarray(s * 4, s * 4 + 4), (y * w + x) * 4);
      if (mask) mask[y * w + x] = img.mask[s];
    }
  }
  return { width: w, height: h, color, mask, offset: img.offset, scale: (img.scale ?? 1) / n };
}

/**
 * The pose table of an actor's body from its pixel art: idle and damaged
 * still frames (content/atlas.js stillPoses), each centred like the
 * original graphics' structures (`centerOffset` plus the art's offset from
 * the footprint centre). Null without pixel art.
 */
export function pixelBodyArt(a) {
  const art = pixelArtOf(a.id);
  if (!art) return null;
  const lookup = pixelLookup();
  const base = a.kind === 'building' ? (a.centerOffset ?? [0, 0]) : [0, 0];
  const offset = [base[0] + art.offset[0], base[1] + art.offset[1]];
  const names = Object.keys(art.poses);
  const images = names.map((name) => upscaled(indexedImage(pixelFrame(art, art.poses[name]), null, lookup, offset), PIXEL_RES));
  return stillPoses(images, names);
}

/**
 * Body slots (2t) of the actors with pixel art: slot -> pose table, for
 * js/sprites.js buildAtlas. Aliases of one id share one table.
 */
export function pixelSlots(actors) {
  const slots = new Map();
  const shared = new Map();
  actors.forEach((a, t) => {
    if (a.kind === 'proxy' || !pixelArtOf(a.id)) return;
    const key = `${String(a.id).toUpperCase()}|${(a.centerOffset ?? [0, 0]).join(',')}`;
    if (!shared.has(key)) shared.set(key, pixelBodyArt(a));
    const art = shared.get(key);
    if (art) slots.set(2 * t, art);
  });
  return slots;
}

/**
 * A draw function (js/sprites.js [w, h, draw]) painting the idle frame of
 * `id`'s pixel art into its footprint box (`a`: rules_json record): the
 * editor's and sidebar's icons (sprites.js drawIcon) and the atlas slot
 * before the pose table replaces it.
 */
export function pixelDraw(a) {
  const art = pixelArtOf(a.id);
  if (!art) return null;
  const frame = pixelFrame(art, art.poses.idle);
  const lookup = pixelLookup();
  const left = ((a.width ?? 1) * 24) / 2 + art.offset[0] - art.width / 2;
  const top = ((a.height ?? 1) * 24) / 2 + art.offset[1] - art.height / 2;
  const shadow = `rgba(0,0,0,${(SHADOW_ALPHA / 255).toFixed(3)})`;
  return (ctx, P) => {
    for (let y = 0; y < frame.height; y++) {
      for (let x = 0; x < frame.width; x++) {
        const v = frame.data[y * frame.width + x];
        if (v === 0) continue;
        const o = v * 4;
        let fill;
        if (lookup.color[o + 3] !== 255) fill = P.c(shadow);
        else if (lookup.mask[v]) fill = P.team(lookup.color[o] / 255);
        else fill = P.c(`rgb(${lookup.color[o]},${lookup.color[o + 1]},${lookup.color[o + 2]})`);
        rect(ctx, fill, left + x, top + y, 1, 1);
      }
    }
  };
}
